        }

        const { x: prevX, y: prevY, width: prevWidth, height: prevHeight } = prevValues;
        const change: XYResizerChange = {};
        const nodeOrigin = node.origin ?? storeNodeOrigin;

        const { width, height, x, y } = getDimensionsAfterResize(
          startValues,
